var c=new LabPttController { RequireGrant=true };
c.Press(0); int e=c.Epoch;
c.Ready(e,10); // WaitingGrant，忽略
c.Grant(e,20); // Keying
c.Ready(e,40); // Tx
c.Release(50);
c.Ready(e,60); // 仍為 Idle，不重新准入

var c=new LabPttController { RequireGrant=true };
c.Press(0); int old=c.Epoch;
c.Release(10); c.Press(20);
c.Grant(old,30); // ignored，Ptt=false
c.Grant(c.Epoch,40); // accepted，Keying
c.Ready(c.Epoch,50); // Tx
